using AdDeliverableManager.Models;
using AdDeliverableManager.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
namespace AdDeliverableManager.Controllers;
[ApiController][Route("internal/relations")][Authorize]
public sealed class RelationsController:ControllerBase
{
    private static readonly string[] AllowedTypes=["DERIVES","VERIFIES","DEPENDS_ON","REFERENCES","REPLACES"];
    private readonly DatabaseService _database;private readonly PermissionService _permissions;
    public RelationsController(DatabaseService database,PermissionService permissions){_database=database;_permissions=permissions;}
    [HttpGet("deliverable/{deliverableId:int}")]public async Task<IActionResult> GetForDeliverable(int deliverableId,CancellationToken ct){if(!await _permissions.HasPermissionAsync(User.GetUserId(),Security.PermissionCatalog.RelationView,deliverableId,ct))return Forbid();await using var c=await _database.OpenConnectionAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT r.Id,r.SourceDeliverableId,sd.DeliverableCode,sd.UnifiedName,st.TypeCode,r.SourceVersionId,sv.InternalVersion,r.TargetDeliverableId,td.DeliverableCode,td.UnifiedName,tt.TypeCode,r.TargetVersionId,tv.InternalVersion,r.RelationType,r.Description,r.CreatedAt FROM DeliverableRelations r JOIN Deliverables sd ON sd.Id=r.SourceDeliverableId JOIN DeliverableTypes st ON st.Id=sd.DeliverableTypeId JOIN Deliverables td ON td.Id=r.TargetDeliverableId JOIN DeliverableTypes tt ON tt.Id=td.DeliverableTypeId LEFT JOIN DeliverableVersions sv ON sv.Id=r.SourceVersionId LEFT JOIN DeliverableVersions tv ON tv.Id=r.TargetVersionId WHERE r.SourceDeliverableId=$id OR r.TargetDeliverableId=$id ORDER BY r.CreatedAt DESC";cmd.Parameters.AddWithValue("$id",deliverableId);var items=new List<object>();await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))items.Add(new{id=reader.GetInt32(0),sourceDeliverableId=reader.GetInt32(1),sourceCode=reader.GetString(2),sourceName=reader.GetString(3),sourceTypeCode=reader.GetString(4),sourceVersionId=reader.IsDBNull(5)?(int?)null:reader.GetInt32(5),sourceVersion=reader.GetNullableString(6),targetDeliverableId=reader.GetInt32(7),targetCode=reader.GetString(8),targetName=reader.GetString(9),targetTypeCode=reader.GetString(10),targetVersionId=reader.IsDBNull(11)?(int?)null:reader.GetInt32(11),targetVersion=reader.GetNullableString(12),relationType=reader.GetString(13),description=reader.GetNullableString(14),createdAt=reader.GetString(15),direction=reader.GetInt32(1)==deliverableId?"OUTGOING":"INCOMING"});return Ok(new{items,relationTypes=RelationTypes()});}
    [HttpGet("candidates")]public async Task<IActionResult> Candidates([FromQuery]int? excludeId,CancellationToken ct){var allowed=await _permissions.GetAllowedDeliverableIdsAsync(User.GetUserId(),Security.PermissionCatalog.RelationCreate,ct);if(allowed.Count==0)return Ok(new{items=Array.Empty<object>()});var allowedSet=allowed.ToHashSet();await using var c=await _database.OpenConnectionAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT d.Id,d.DeliverableCode,d.UnifiedName,t.TypeCode,t.TypeName,p.ProjectName,d.CurrentVersionId,v.InternalVersion FROM Deliverables d JOIN DeliverableTypes t ON t.Id=d.DeliverableTypeId JOIN Projects p ON p.Id=d.ProjectId LEFT JOIN DeliverableVersions v ON v.Id=d.CurrentVersionId WHERE d.LifecycleStatus='ACTIVE' AND ($excludeId IS NULL OR d.Id<>$excludeId) ORDER BY p.ProjectName,t.SortOrder,d.DeliverableCode";cmd.Parameters.AddWithValue("$excludeId",excludeId);var items=new List<object>();await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct)){var id=reader.GetInt32(0);if(!allowedSet.Contains(id))continue;items.Add(new{id,code=reader.GetString(1),name=reader.GetString(2),typeCode=reader.GetString(3),type=reader.GetString(4),project=reader.GetString(5),currentVersionId=reader.IsDBNull(6)?(int?)null:reader.GetInt32(6),currentVersion=reader.GetNullableString(7)});}return Ok(new{items});}
    [HttpGet("versions/{deliverableId:int}")]public async Task<IActionResult> Versions(int deliverableId,CancellationToken ct){if(!await _permissions.HasPermissionAsync(User.GetUserId(),Security.PermissionCatalog.RelationCreate,deliverableId,ct))return Forbid();await using var c=await _database.OpenConnectionAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT Id,InternalVersion,VersionStatus FROM DeliverableVersions WHERE DeliverableId=$id ORDER BY CreatedAt DESC";cmd.Parameters.AddWithValue("$id",deliverableId);var items=new List<object>();await using var reader=await cmd.ExecuteReaderAsync(ct);while(await reader.ReadAsync(ct))items.Add(new{id=reader.GetInt32(0),version=reader.GetString(1),status=reader.GetString(2)});return Ok(new{items});}
    [HttpPost]public async Task<IActionResult> Create([FromBody]RelationCreateRequest request,CancellationToken ct){if(request.SourceDeliverableId<=0||request.TargetDeliverableId<=0)return BadRequest(new{message="必须选择源交付物和目标交付物。"});if(request.SourceDeliverableId==request.TargetDeliverableId)return BadRequest(new{message="交付物不能与自身建立关联。"});if(!AllowedTypes.Contains(request.RelationType,StringComparer.Ordinal))return BadRequest(new{message="关联类型无效。"});if(!await _permissions.HasPermissionAsync(User.GetUserId(),Security.PermissionCatalog.RelationCreate,request.SourceDeliverableId,ct)||!await _permissions.HasPermissionAsync(User.GetUserId(),Security.PermissionCatalog.RelationCreate,request.TargetDeliverableId,ct))return Forbid();await using var c=await _database.OpenConnectionAsync(ct);using var tx=c.BeginTransaction();if(!await DeliverableExistsAsync(c,tx,request.SourceDeliverableId,ct)||!await DeliverableExistsAsync(c,tx,request.TargetDeliverableId,ct))return BadRequest(new{message="源交付物或目标交付物不存在。"});if(!await VersionBelongsAsync(c,tx,request.SourceVersionId,request.SourceDeliverableId,ct)||!await VersionBelongsAsync(c,tx,request.TargetVersionId,request.TargetDeliverableId,ct))return BadRequest(new{message="所选版本不属于对应交付物。"});await using var duplicate=c.CreateCommand();duplicate.Transaction=tx;duplicate.CommandText="SELECT COUNT(*) FROM DeliverableRelations WHERE SourceDeliverableId=$source AND TargetDeliverableId=$target AND RelationType=$type AND COALESCE(SourceVersionId,0)=COALESCE($sourceVersion,0) AND COALESCE(TargetVersionId,0)=COALESCE($targetVersion,0)";duplicate.Parameters.AddWithValue("$source",request.SourceDeliverableId);duplicate.Parameters.AddWithValue("$target",request.TargetDeliverableId);duplicate.Parameters.AddWithValue("$type",request.RelationType);duplicate.Parameters.AddWithValue("$sourceVersion",request.SourceVersionId);duplicate.Parameters.AddWithValue("$targetVersion",request.TargetVersionId);if(Convert.ToInt32(await duplicate.ExecuteScalarAsync(ct))>0)return Conflict(new{message="相同关联关系已经存在。"});var now=DateTime.UtcNow.ToString("O");await using var insert=c.CreateCommand();insert.Transaction=tx;insert.CommandText="INSERT INTO DeliverableRelations(SourceDeliverableId,SourceVersionId,TargetDeliverableId,TargetVersionId,RelationType,Description,CreatedAt) VALUES($source,$sourceVersion,$target,$targetVersion,$type,$description,$now);SELECT last_insert_rowid()";insert.Parameters.AddWithValue("$source",request.SourceDeliverableId);insert.Parameters.AddWithValue("$sourceVersion",request.SourceVersionId);insert.Parameters.AddWithValue("$target",request.TargetDeliverableId);insert.Parameters.AddWithValue("$targetVersion",request.TargetVersionId);insert.Parameters.AddWithValue("$type",request.RelationType);insert.Parameters.AddWithValue("$description",request.Description);insert.Parameters.AddWithValue("$now",now);var id=Convert.ToInt32(await insert.ExecuteScalarAsync(ct));await InsertAuditAsync(c,tx,id,"CREATE_RELATION",User.GetDisplayName(),$"建立交付物关联 {request.RelationType}",now,ct);await tx.CommitAsync(ct);return Ok(new{id,message="交付物关联已建立。"});}
    [HttpDelete("{id:int}")]public async Task<IActionResult> Delete(int id,CancellationToken ct){await using var c=await _database.OpenConnectionAsync(ct);using var tx=c.BeginTransaction();await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="SELECT SourceDeliverableId,TargetDeliverableId FROM DeliverableRelations WHERE Id=$id";cmd.Parameters.AddWithValue("$id",id);await using var reader=await cmd.ExecuteReaderAsync(ct);if(!await reader.ReadAsync(ct))return NotFound(new{message="关联关系不存在。"});var source=reader.GetInt32(0);var target=reader.GetInt32(1);await reader.DisposeAsync();if(!await _permissions.HasPermissionAsync(User.GetUserId(),Security.PermissionCatalog.RelationDelete,source,ct)||!await _permissions.HasPermissionAsync(User.GetUserId(),Security.PermissionCatalog.RelationDelete,target,ct))return Forbid();await using var delete=c.CreateCommand();delete.Transaction=tx;delete.CommandText="DELETE FROM DeliverableRelations WHERE Id=$id";delete.Parameters.AddWithValue("$id",id);await delete.ExecuteNonQueryAsync(ct);var now=DateTime.UtcNow.ToString("O");await InsertAuditAsync(c,tx,id,"DELETE_RELATION",User.GetDisplayName(),"删除交付物关联",now,ct);await tx.CommitAsync(ct);return Ok(new{message="关联关系已删除。"});}
    private static object[] RelationTypes()=>[new{code="DERIVES",name="派生"},new{code="VERIFIES",name="验证"},new{code="DEPENDS_ON",name="依赖"},new{code="REFERENCES",name="引用"},new{code="REPLACES",name="替代"}];
    private static async Task<bool> DeliverableExistsAsync(SqliteConnection c,SqliteTransaction tx,int id,CancellationToken ct){await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="SELECT COUNT(*) FROM Deliverables WHERE Id=$id";cmd.Parameters.AddWithValue("$id",id);return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct))>0;}
    private static async Task<bool> VersionBelongsAsync(SqliteConnection c,SqliteTransaction tx,int? versionId,int deliverableId,CancellationToken ct){if(!versionId.HasValue)return true;await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="SELECT COUNT(*) FROM DeliverableVersions WHERE Id=$versionId AND DeliverableId=$deliverableId";cmd.Parameters.AddWithValue("$versionId",versionId);cmd.Parameters.AddWithValue("$deliverableId",deliverableId);return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct))>0;}
    private static async Task InsertAuditAsync(SqliteConnection c,SqliteTransaction tx,int id,string action,string operatorName,string summary,string now,CancellationToken ct){await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO AuditLogs(EntityType,EntityId,ActionType,Operator,Summary,CreatedAt) VALUES('Relation',$id,$action,$operator,$summary,$now)";cmd.Parameters.AddWithValue("$id",id);cmd.Parameters.AddWithValue("$action",action);cmd.Parameters.AddWithValue("$operator",operatorName);cmd.Parameters.AddWithValue("$summary",summary);cmd.Parameters.AddWithValue("$now",now);await cmd.ExecuteNonQueryAsync(ct);}
}
